import { DatePicker } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function DatePickerExample() {
  const [date, setDate] = useState<Date | null>(null);
  return (
    <div style={stack}>
      <DatePicker label="Review date" value={date} onChange={setDate} />
      <p role="status">
        {date ? `Review: ${date.toLocaleDateString('en')}` : 'No date selected.'}
      </p>
    </div>
  );
}
export function Example() {
  return <DatePickerExample />;
}

